// adminGroupDocPut: PUT /api/v1/admin/groups/{id}/doc — replaces the
// group's per-source mute document WHOLE (never merged) together with its
// schema version (SetGroupDoc's whole-replace contract). Validation is
// SHAPE-only (the putProfilePrefs law): the body's `doc` must be one JSON
// object; its contents are opaque and stored verbatim — the read side
// parses only the "mutes" vocabulary and skips a document it cannot read
// (visibility never depends on doc hygiene). schema_version defaults to 1
// when the body omits it. 204 on success.
//
// @Summary     Replace a group's mute document
// @Tags        admin
// @ID          admin-groups-doc-put
// @Router      /admin/groups/{id}/doc [put]
// @Param       id   path int    true "group id"
// @Param       body body object true "{doc (JSON object), schema_version?}"
// @Success     204 "document replaced whole; the next group GET serves it verbatim"
// @Failure     400 {object} errorBody "malformed body, or doc not a JSON object"
// @Failure     401 {object} errorBody
// @Failure     403 {object} errorBody
// @Failure     404 {object} errorBody "unknown group id"
// @Failure     500 {object} errorBody
// @Failure     503 {object} errorBody
func (a *app) adminGroupDocPut(w http.ResponseWriter, r *http.Request) {
	idsvc, g, ok := a.adminGroupResolve(w, r)
	if !ok {
		return
	}
	var req struct {
		Doc           json.RawMessage `json:"doc"`
		SchemaVersion *int            `json:"schema_version"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "malformed JSON body", false)
		return
	}
	// Shape-only: the document must be one JSON object (null is not an
	// object — Unmarshal leaves the map nil without error, refused). The
	// contents are opaque: stored verbatim, vocabulary never validated
	// here (the read side skips what it cannot read).
	var doc map[string]any
	if err := json.Unmarshal(req.Doc, &doc); err != nil || doc == nil {
		writeError(w, http.StatusBadRequest, "bad_request",
			"doc must be a JSON object", false)
		return
	}
	version := 1
	if req.SchemaVersion != nil {
		version = *req.SchemaVersion
	}
	if err := idsvc.SetGroupDoc(r.Context(), g.Name, string(req.Doc), version); err != nil {
		a.adminGroupError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}
